n, fraudulent affiliation or forged evidence can result in removal, suspension and may be referred for legal action where applicable.',style:AppTheme.body(11,color:AppColors.sub))),const SizedBox(height:8),SizedBox(width:double.infinity,height:48,child:ElevatedButton(onPressed:_busy||!_legal?null:submit,child:_busy?const CircularProgressIndicator(strokeWidth:2,color:AppColors.black):const Text('SUBMIT FOR HUMAN REVIEW')))])),const SizedBox(height:28),Text('MY APPLICATIONS',style:AppTheme.display(20)),const SizedBox(height:10),FutureBuilder<List<VerificationApplication>>(future:_apps,builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const CircularProgressIndicator();final a=s.data??[];if(a.isEmpty)return Text('No applications yet.',style:AppTheme.body(12,color:AppColors.sub));return Column(children:a.map((x)=>Card(child:Column(children:[ListTile(title:Text('${x.claimedName} · ${x.role.toUpperCase()}'),subtitle:Text(x.rejectionReason??'Submitted ${x.submittedAt.toLocal()}'),trailing:Text(x.status.toUpperCase())),FutureBuilder<Map<String,dynamic>?>(future:_repo.domainChallenge(x.id),builder:(context,d){final c=d.data;if(c==null||c['verified_at']!=null)return const SizedBox.shrink();return Padding(padding:const EdgeInsets.fromLTRB(16,0,16,12),child:Text('DOMAIN PROOF: add TXT ${c['token']} to _fuskamo-verify.${c['domain']}. FUSKAMO staff can then check it. This proves control of the domain, not ownership of the organization by itself.',style:AppTheme.body(10,color:AppColors.amber)));})]))).toList());})]));
